from pathlib import Path

p=Path('vendor-dashboard.html')
s=p.read_text(encoding='utf-8')

old_city="function orderCity(o){const d=normalizeOrderDetails(o?.details);return d.governorate||d.city||d.province||d.customer_city||'غير محددة'}"
new_city="function orderCity(o){const d=normalizeOrderDetails(o?.details);return d.governorate||d.city||d.province||d.customer_city||o?.city||o?.governorate||'غير محددة'}\nfunction orderPaymentStatus(o){const d=normalizeOrderDetails(o?.details),raw=String(d.payment_method||d.payment_status||o?.payment_status||'').trim(),v=raw.toLowerCase();if(/paid|prepaid|تم الدفع|مدفوع/.test(v))return 'تم الدفع مسبقاً';if(/cod|cash|عند الاستلام|نقد/.test(v))return 'الدفع عند الاستلام - COD';return raw||'الدفع عند الاستلام - COD'}"
if old_city not in s: raise SystemExit('orderCity target not found')
s=s.replace(old_city,new_city,1)

start=s.index('function printShippingLabel(orderId){')
end=s.index('\n\nObject.assign(window',start)
old=s[start:end]
new=r'''function printShippingLabel(orderId){const o=orders.find(x=>String(x.id)===String(orderId));if(!o)return showNotice('تعذر العثور على الطلب للطباعة.',true);const code=o.order_code||String(o.id).slice(0,8),product=orderProductName(o),qty=orderQuantity(o),city=orderCity(o),payment=orderPaymentStatus(o),date=new Date(o.created_at).toLocaleDateString('ar-IQ');const w=window.open('','_blank','width=520,height=760');if(!w)return showNotice('يرجى السماح بالنوافذ المنبثقة لطباعة الملصق.',true);w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>MeshWar Cargo - ${esc(code)}</title><style>*{box-sizing:border-box}html,body{margin:0;padding:0;font-family:Arial,sans-serif;color:#0f172a;background:#fff}.label-container{width:100mm;max-width:100%;min-height:0;border:2px solid #0f172a;border-radius:3mm;padding:4mm;display:flex;flex-direction:column;gap:3mm;box-sizing:border-box;overflow:hidden}.brand{text-align:center;border-bottom:2px solid #0f172a;padding-bottom:2mm}.brand h1{margin:0;font-size:18pt}.brand p{margin:1mm 0 0;font-size:8.5pt}.order{text-align:center;font-size:17pt;font-weight:900;direction:ltr}.barcode{height:22mm;display:flex;align-items:center;justify-content:center}.barcode svg{max-width:100%;height:100%}.grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #cbd5e1}.cell{padding:3mm;border:1px solid #cbd5e1}.label-title{font-size:7.5pt;color:#64748b;margin-bottom:1mm}.value{font-size:10.5pt;font-weight:800}.product{grid-column:1/-1}.privacy{margin-top:auto;text-align:center;font-size:7.5pt;color:#64748b;border-top:1px dashed #94a3b8;padding-top:2mm}@media print{@page{size:auto;margin:0mm}html,body{height:100%;margin:0!important;padding:0!important;overflow:hidden}.label-container{page-break-inside:avoid;page-break-after:avoid;break-inside:avoid;max-height:98vh;box-sizing:border-box}body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"><\/script></head><body><div class="label-container"><div class="brand"><h1>MeshWar Cargo</h1><p>ملصق شحن متجر محلي</p></div><div class="order">${esc(code)}</div><div class="barcode"><svg id="barcode"></svg></div><div class="grid"><div class="cell product"><div class="label-title">المنتج</div><div class="value">${esc(product)}</div></div><div class="cell"><div class="label-title">الكمية</div><div class="value">${qty}</div></div><div class="cell"><div class="label-title">التاريخ</div><div class="value">${esc(date)}</div></div><div class="cell"><div class="label-title">المحافظة / المدينة</div><div class="value">${esc(city)}</div></div><div class="cell"><div class="label-title">حالة الدفع</div><div class="value">${esc(payment)}</div></div></div><div class="privacy">بيانات التواصل والعنوان التفصيلي محفوظة لدى منصة MeshWar فقط.</div></div><script>window.addEventListener('load',()=>{try{JsBarcode('#barcode',${JSON.stringify(String(code))},{format:'CODE128',displayValue:false,height:58,margin:0,width:2})}catch(e){console.error(e)}setTimeout(()=>window.print(),250)});<\/script></body></html>`);w.document.close()}'''
s=s[:start]+new+s[end:]
p.write_text(s,encoding='utf-8')
